function arc(s, { apex, riseExp, fallExp }) {
  if (s <= 0 || s >= 1)
    return 0;
  return s < apex ? 1 - Math.pow(1 - s / apex, riseExp) : 1 - Math.pow((s - apex) / (1 - apex), fallExp);
}

