function makeWeapon(id, look, { slide = 0 } = {}) {
  if (id === "sword") {
    const s = makeSword(look);
    return { ...s, info: { len: SWORD.total, strike: [[0, 0, SWORD.guard], [0, 0, SWORD.tip]], off: null, shield: null } };
  }
  const build = MODELS[id];
  if (!build)
    throw new Error(`no weapon model "${id}"`);
  const m = soup();
  const o = soup();
  const info = build(m, o);
  const geos = [];
  const { metal, rest } = weaponMaterials(look);
  const add = (s, mat) => {
    const g = s.geometry();
    if (!g.getAttribute("position")?.count)
      return;
    if (info.turnZtoY)
      g.rotateX(-Math.PI / 2);
    geos.push([g, mat]);
  };
  add(m, metal);
  add(o, rest);
  if (info.turnZtoY) {
    const g = info.turnZtoY.geometry();
    g.rotateX(-Math.PI / 2);
    geos.push([g, metal]);
  }
  if (info.flanges) {
    const f = soup();
    for (let i = 0;i < info.flanges.n; i++) {
      const a = i / info.flanges.n * TAU2, c = Math.cos(a), sn = Math.sin(a);
      const pts = [[0.12, 6.45], [0.78, 6.85], [0.84, 7.6], [0.12, 8.05]];
      const P = (y, z, x) => [x * c - y * sn, x * sn + y * c, z];
      for (let k = 0;k < pts.length; k++) {
        const [y0, z0] = pts[k], [y1, z1] = pts[(k + 1) % pts.length];
        f.quad(P(y0, z0, -0.06), P(y1, z1, -0.06), P(y1, z1, 0.06), P(y0, z0, 0.06), COL2.gold);
      }
      f.tri(P(0.12, 6.45, 0.06), P(0.78, 6.85, 0.06), P(0.84, 7.6, 0.06), COL2.gold);
      f.tri(P(0.12, 6.45, 0.06), P(0.84, 7.6, 0.06), P(0.12, 8.05, 0.06), COL2.gold);
      f.tri(P(0.12, 6.45, -0.06), P(0.84, 7.6, -0.06), P(0.78, 6.85, -0.06), COL2.goldDark);
      f.tri(P(0.12, 6.45, -0.06), P(0.12, 8.05, -0.06), P(0.84, 7.6, -0.06), COL2.goldDark);
    }
    geos.push([f.geometry(), metal]);
  }
  if (slide)
    for (const [g] of geos)
      g.translate(0, 0, -slide);
  const group = new hn;
  const meshes = geos.map(([g, mat]) => new Tt(g, mat));
  const hulls = geos.map(([g]) => new Tt(hullOf(g), outlineMaterial(look, { color: 1052427, warm: 3813926, px: 1.1 })));
  for (const me of meshes)
    me.castShadow = true;
  group.add(...meshes, ...hulls);
  const strike = info.strike && slide ? info.strike.map(([x, y, z]) => [x, y, z - slide]) : info.strike;
  const triangles = geos.reduce((a, [g]) => a + g.getAttribute("position").count / 3, 0);
  return {
    group,
    base: strike ? new U(...strike[0]) : new U(0, 0, 0),
    tip: strike ? new U(...strike[1]) : new U(0, 0, info.len / 2),
    meshes,
    hulls,
    materials: [metal, rest],
    triangles,
    info: { len: info.len, strike, off: info.off != null ? info.off - slide : null, shield: info.shield || null, glow: info.glow || null, slide, carrySlide: info.carrySlide ?? 0 },
    dispose() {
      for (const me of [...meshes, ...hulls]) {
        me.geometry.dispose();
        me.material.dispose();
      }
    }
  };
}

