function applyMood(mood, { sun, sky, look, clear }) {
  if (mood.sun) {
    if (mood.sun.color != null)
      sun.color.setHex(mood.sun.color);
    if (mood.sun.intensity != null)
      sun.intensity = mood.sun.intensity;
    if (mood.sun.elev != null || mood.sun.az != null) {
      const e = (mood.sun.elev ?? 65) * Math.PI / 180;
      const a = (mood.sun.az ?? 0) * Math.PI / 180;
      sun.position.set(Math.sin(a) * Math.cos(e), Math.sin(e), -Math.cos(a) * Math.cos(e)).multiplyScalar(250);
    }
  }
  if (mood.sky) {
    if (mood.sky.top != null)
      sky.color.setHex(mood.sky.top);
    if (mood.sky.bottom != null)
      sky.groundColor.setHex(mood.sky.bottom);
    if (mood.sky.intensity != null)
      sky.intensity = mood.sky.intensity;
  }
  if (mood.litTint != null)
    look.uLitTint.value.setHex(mood.litTint);
  if (mood.shadeTint)
    look.uShadeTint.value.set(...mood.shadeTint);
  if (mood.pool) {
    if (mood.pool.size != null)
      look.uPool.value.set(0, 0, 60 * mood.pool.size, 40 * mood.pool.size);
    if (mood.pool.floor != null)
      look.uPoolFloor.value = mood.pool.floor;
  }
  if (mood.lant) {
    if (mood.lant.color != null)
      look.uLantColor.value.setHex(mood.lant.color);
    if (mood.lant.power != null)
      look.uLantPower.value = mood.lant.power;
  }
  if (mood.clear != null)
    clear.setHex(mood.clear);
}

// site/js/gfx/wind.js
var DIR_X = 0.946;
var DIR_Y = 0.324;
var FRONT_SPEED = 150;
var FRONT_START = -200;
function makeWind({ speed = 26, gustEvery = 7.5, strength = 1 } = {}) {
  let t = 0;
  let gustFrom = -1e9;
  let nextGust = 3;
  const gustAt = (x, y) => {
    const u = FRONT_START + (t - gustFrom) * FRONT_SPEED - (x * DIR_X + y * DIR_Y);
    if (u < -48)
      return 0;
    return u < 0 ? Math.exp(-((u / 16) ** 2)) : Math.exp(-u / 110);
  };
  return {
    step(dt) {
      t += dt;
      if (t > nextGust) {
        gustFrom = t;
        nextGust = t + gustEvery * (0.6 + Math.random() * 0.9);
      }
    },
    get t() {
      return t;
    },
    at(x, y, flex = 1) {
      const phase = x * 0.035 + y * 0.012 - t * (speed * 0.035);
      const base = Math.sin(phase) * 0.6 + Math.sin(phase * 2.3 + 1.7) * 0.25;
      const breath = Math.sin(t * 0.7) * 0.3 + 0.7;
      const g = gustAt(x, y) * (Math.sin(phase * 1.3) * 0.3 + 0.8);
      return (base * breath + g * 1.8) * strength * flex;
    },
    drift(x, y, flex = 1) {
      const w = this.at(x, y, flex);
      return [w * 6, w * 1.4];
    },
    get gust() {
      return gustAt(0, 0);
    }
  };
}

// site/js/gfx3d/debug3d.js
function makeDebug3D(scene) {
  const geo = new ot;
  const mat = new Ti({ color: 9437136, toneMapped: false, depthTest: false, transparent: true, opacity: 0.9 });
  const lines = new cs(geo, mat);
  lines.frustumCulled = false;
  lines.renderOrder = 50;
  lines.visible = false;
  scene.add(lines);
  const v = [];
  const ring = (x, y, r, h = 0.15, n = 40) => {
    for (let i = 0;i < n; i++) {
      const a0 = i / n * Math.PI * 2;
      const a1 = (i + 1) / n * Math.PI * 2;
      v.push(x + Math.cos(a0) * r, h, y + Math.sin(a0) * r, x + Math.cos(a1) * r, h, y + Math.sin(a1) * r);
    }
  };
  return {
    update(w, on) {
      lines.visible = !!on;
      if (!on)
        return;
      v.length = 0;
      const p = w.player;
      ring(p.x, p.y, 6);
      const b = w.boss;
      if (b) {
        ring(b.x, b.y, b.r);
        if (b.hurt) {
          const [ha, hc] = b.hurt, c = Math.cos(b.face), s = Math.sin(b.face), n = 40;
          const pt = (i) => {
            const t = i / n * Math.PI * 2, u = Math.cos(t) * ha, q = Math.sin(t) * hc;
            return [b.x + u * c - q * s, b.y + u * s + q * c];
          };
          for (let i = 0;i < n; i++) {
            const [x0, y0] = pt(i), [x1, y1] = pt(i + 1);
            v.push(x0, 0.3, y0, x1, 0.3, y1);
          }
        }
        v.push(b.x, 0.15, b.y, b.x, (b.hitH || 34) * H_TO_3D, b.y);
      }
      for (const a of w.adds)
        if (a.alive)
          ring(a.x, a.y, a.r || 7);
      for (const s of w.shots)
        if (!s.dead)
          ring(s.x, s.y, s.r || 6, 5);
      const arc = swingArc(p);
      if (arc) {
        const n = 4;
        for (let i = 0;i <= n; i++) {
          const a = arc.a0 + (arc.a1 - arc.a0) * i / n;
          v.push(arc.x, 0.2, arc.y, arc.x + Math.cos(a) * arc.r, 0.2, arc.y + Math.sin(a) * arc.r);
        }
      }
      geo.setAttribute("position", new Xe(v, 3));
      geo.computeBoundingSphere();
    }
  };
}
function makeBenchOverlays(scene, L, { bogplane = false, layout = false } = {}) {
  const made = [];
  if (bogplane) {
    const W = 2988;
    const H = 2080;
    const PPU = 6.5317;
    const mat = new Kt({
      uniforms: { tMap: { value: null }, uK: { value: [PPU / W, 0.5 * PPU / H] } },
      vertexShader: `
        varying vec3 vW;
        void main() {
          vec4 w = modelMatrix * vec4(position, 1.0);
          vW = w.xyz;
          gl_Position = projectionMatrix * viewMatrix * w;
        }`,
      fragmentShader: `
        uniform sampler2D tMap;
        uniform vec2 uK;
        varying vec3 vW;
        void main() {
          vec2 uv = vec2(0.5 + (vW.x - vW.z) * uK.x, 0.5 - (vW.x + vW.z) * uK.y);
          if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) discard;
          gl_FragColor = texture2D(tMap, vec2(uv.x, 1.0 - uv.y));
          #include <colorspace_fragment>
        }`,
      polygonOffset: true,
      polygonOffsetFactor: -2,
      polygonOffsetUnits: -2
    });
    const plane = new Tt(new hs(700, 700), mat);
    plane.rotation.x = -Math.PI / 2;
    plane.position.y = 0.02;
    plane.renderOrder = -1;
    plane.visible = false;
    const img = new Image;
    img.onload = () => {
      const t = new ol(img);
      t.colorSpace = kn;
      t.minFilter = bt;
      t.generateMipmaps = false;
      mat.uniforms.tMap.value = t;
      plane.visible = true;
    };
    img.src = "art/bog.webp";
    scene.add(plane);
    made.push(plane);
  }
  if (layout) {
    const v = [];
    const ring = (x, y, r, n = 32) => {
      for (let i = 0;i < n; i++) {
        const a0 = i / n * Math.PI * 2;
        const a1 = (i + 1) / n * Math.PI * 2;
        v.push(x + Math.cos(a0) * r, 0.3, y + Math.sin(a0) * r, x + Math.cos(a1) * r, 0.3, y + Math.sin(a1) * r);
      }
    };
    const cross = (x, y, r) => v.push(x - r, 0.3, y, x + r, 0.3, y, x, 0.3, y - r, x, 0.3, y + r);
    for (const t of L.trees)
      ring(t.x, t.y, t.flare), cross(t.x, t.y, t.flare * 0.6);
    for (const l of L.lanterns)
      ring(l.x, l.y, LANTERN.plinth / 2, 4), cross(l.x, l.y, 2);
    for (const b of L.bushes)
      ring(b.x, b.y, b.radius);
    ring(L.topiary.x, L.topiary.y, L.topiary.radius);
    for (const l of L.lupines)
      ring(l.x, l.y, 2, 12);
    for (const c of L.clovers)
      ring(c.x, c.y, c.across / 2, 16);
    const props = new ot;
    props.setAttribute("position", new Xe(v, 3));
    const lines = new cs(props, new Ti({ color: 16732120, toneMapped: false, depthTest: false, transparent: true, opacity: 0.95 }));
    v.length = 0;
    ring(0, 0, ARENA.R, 128);
    const edgeGeo = new ot;
    edgeGeo.setAttribute("position", new Xe(v.slice(), 3));
    const edge = new cs(edgeGeo, new Ti({ color: 5236991, toneMapped: false, depthTest: false, transparent: true, opacity: 0.9 }));
    v.length = 0;
    ring(0, 0, R_SEEN, 128);
    const seenGeo = new ot;
    seenGeo.setAttribute("position", new Xe(v.slice(), 3));
    const seen = new cs(seenGeo, new Ti({ color: 16773754, toneMapped: false, depthTest: false, transparent: true, opacity: 0.6 }));
    for (const o of [lines, edge, seen]) {
      o.frustumCulled = false;
      o.renderOrder = 49;
      scene.add(o);
      made.push(o);
    }
  }
  return {
    dispose() {
      for (const o of made) {
        scene.remove(o);
        o.geometry.dispose();
        o.material.uniforms?.tMap.value?.dispose();
        o.material.dispose();
      }
    }
  };
}

// site/js/gfx3d/tiers3d.js
var TIERS2 = {
  low: { shadow: 512, lanterns: 4, bloom: 0, next: null },
  medium: { shadow: 1024, lanterns: 5, bloom: 0.35, next: "low" },
  high: { shadow: 2048, lanterns: 5, bloom: 0.35, next: "medium" }
};
var KEY = "threebells.tier3d";
var CALM = "threebells.tier3dCalm";
function startTier() {
  try {
    const saved = localStorage.getItem(KEY);
    if (saved && TIERS2[saved])
      return saved;
  } catch {}
  const coarse = typeof matchMedia === "function" && matchMedia("(pointer: coarse)").matches;
  if (!coarse)
    return "high";
  const cores = navigator.hardwareConcurrency || 4;
  return cores >= 8 && (window.devicePixelRatio || 1) >= 3 ? "high" : "medium";
}
function saveTier(t) {
  try {
    localStorage.setItem(KEY, t);
    localStorage.setItem(CALM, "0");
  } catch {}
}
function afterFight(tier, smooth) {
  try {
    const calm = smooth ? Number(localStorage.getItem(CALM) || 0) + 1 : 0;
    const up = Object.keys(TIERS2).find((k) => TIERS2[k].next === tier);
    if (calm >= 3 && up) {
      saveTier(up);
      return up;
    }
    localStorage.setItem(CALM, String(calm));
  } catch {}
  return null;
}
function makeTierMonitor() {
  const gaps = [];
  let last = null;
  let refresh = 1000 / 60;
  let decided = false;
  let over = 0;
  let cuts = 0;
  let fightFrames = 0;
  let slowFrames = 0;
  return {
    get refreshMs() {
      return refresh;
    },
    get smooth() {
      return fightFrames >= 600 && slowFrames < fightFrames * 0.01 && cuts === 0;
    },
    frame(now, intro) {
      const gap = last == null ? null : now - last;
      last = now;
      if (gap == null || gap > 250)
        return null;
      if (intro) {
        gaps.push(gap);
        return null;
      }
      if (!decided) {
        decided = true;
        if (gaps.length >= 20) {
          const sorted = [...gaps].sort((a, b) => a - b);
          const med = sorted[sorted.length >> 1];
          refresh = [1000 / 144, 1000 / 120, 1000 / 90, 1000 / 60].reduce((b, r) => Math.abs(r - med) < Math.abs(b - med) ? r : b, 1000 / 60);
          const p90 = sorted[Math.floor(sorted.length * 0.9)];
          if (p90 > refresh * 1.5)
            return { drop: true };
        }
        return null;
      }
      fightFrames++;
      if (gap > refresh * 1.25)
        slowFrames++;
      over = gap > refresh * 1.25 ? over + 1 : 0;
      if (over >= 30) {
        over = 0;
        return { cut: ++cuts };
      }
      return null;
    }
  };
}

