        const x = b.x + Math.cos(a) * 12, y = b.y + Math.sin(a) * 12;
        puff(0, x, gy(x, y, R(2, 10)), y, Math.cos(a) * R(90, 150), R(10, 40), Math.sin(a) * R(90, 150), R(0.45, 0.7), 5, 11, { buoy: 30, drag: 0.93 });
