          P(e.x, e.y, big ? 14 : 8, { speed: 75, life: 0.55, cols: ["#e9f6f8", "#cfe6ec", "#ffffff"], spread: 6.3, grav: 380, vz: 70, z: 12, size: sz(0.9, 1.6), drag: 0.93, kind: "water" });
          const bogLife = ctx.bogLife;
