          P(e.x, e.y, 14, { speed: 80, life: 0.55, cols: ["#e9f6f8", "#cfe6ec", "#ffffff"], dir: e.a, spread: 2.4, grav: 380, vz: 70, z: 12, size: sz(0.9, 1.7), drag: 0.93, kind: "water" });
