          P(e.x, e.y, 6, { speed: 45, life: 0.55, cols: ["#1f6a4a", "#24382e", "#9a1c12"], grav: 380, vz: 50, z: fy, size: sz(1, 1.6), drag: 0.93, kind: "water" });
