      rc.camera.layers.set(1);
      jobs.push(rc.gl.compileAsync(draws(rc.scene, 1), rc.camera, passView(rc.scene, "glow")));
      rc.gl.setRenderTarget(rc.post.fade);
      rc.camera.layers.set(2);
      jobs.push(rc.gl.compileAsync(draws(rc.scene, 2), rc.camera, passView(rc.scene, "fade")));
      rc.gl.setRenderTarget(rc.post.decal);
